package cn.lili.modules.community.p0.stage45;
import cn.lili.modules.community.p0.support.*;import com.google.gson.*;import org.junit.jupiter.api.*;import java.security.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import static cn.lili.modules.community.p0.support.Stage1Json.*;import static org.junit.jupiter.api.Assertions.*;
/** Pure mapper/signature contract using generated RSA keys. Never contacts any provider or local HTTP. */
class Stage45WechatFundsTest {
 static KeyPair keys;static Stage45WechatFunds adapter;static final Instant AT=Instant.parse("2026-11-02T09:30:00Z");
 @BeforeAll static void open()throws Exception{var gen=KeyPairGenerator.getInstance("RSA");gen.initialize(2048);keys=gen.generateKeyPair();var credentials=object(map("merchantId","12345678","merchantSerialNumber","UNIT_SERIAL","publicKeyId","UNIT_PUBLIC","privateKeyPkcs8",Base64.getEncoder().encodeToString(keys.getPrivate().getEncoded()),"publicKeyX509",Base64.getEncoder().encodeToString(keys.getPublic().getEncoded())));adapter=new Stage45WechatFunds(credentials,new Stage45WechatFunds.Authority(){public JsonObject original(JsonObject r){throw new AssertionError("No provider evidence read");}public JsonObject capability(JsonObject r,String k){throw new AssertionError("No provider capability read");}public JsonObject capacity(JsonObject r,String k,String s){throw new AssertionError("No provider capacity read");}public JsonObject bill(String a,LocalDate d,Instant c){throw new AssertionError("No bill read");}public boolean trusted(JsonObject p){return false;}},()->false);}
 JsonObject request(String kind){return object(map("mode","REAL","currency","CNY","platformMerchantId","12345678","applicationId","wx_UNIT","payerMemberId","2","orderId","3","storeId","4","transactionId","UNIT_TRANSACTION","subMchid","23456789","requestNo","S45_UNIT_REQUEST","receiverMchid","34567890","originalShareRequest","S45_UNIT_SHARE","amountCent",kind.equals("FINISH")?0:500,"paidCent",10000,"fundingAccount","ORIGINAL_TRANSACTION"));}
 JsonObject proof(JsonObject request,JsonObject body,boolean query)throws Exception{var call=Stage45WechatFunds.call(request,query);String raw=write(body),timestamp=String.valueOf(AT.getEpochSecond()),nonce="UNIT_NONCE";var signer=Signature.getInstance("SHA256withRSA");signer.initSign(keys.getPrivate());signer.update((timestamp+"\n"+nonce+"\n"+raw+"\n").getBytes(StandardCharsets.UTF_8));return object(map("method",call.method(),"uri",call.uri(),"httpStatus",200,"observedAt",AT,"body",raw,"headers",map("Wechatpay-Timestamp",timestamp,"Wechatpay-Nonce",nonce,"Wechatpay-Serial","UNIT_PUBLIC","Wechatpay-Signature",Base64.getEncoder().encodeToString(signer.sign()))));}
 JsonObject sharing(String second){return object(map("sub_mchid","23456789","transaction_id","UNIT_TRANSACTION","out_order_no","S45_UNIT_REQUEST","status","FINISHED","receivers",List.of(map("detail_id","DETAIL1","type","MERCHANT_ID","receiver_account","34567890","amount",300,"result","SUCCESS"),map("detail_id","DETAIL2","type","MERCHANT_ID","receiver_account","34567890","amount",200,"result",second))));}

 @Test void missingOrAlreadyUnfrozenOriginalStateCannotAuthorizeShare()throws Exception{
  var r=request("SHARE");r.addProperty("kind","SHARE");var authority=org.mockito.Mockito.mock(Stage45WechatFunds.Authority.class);var p=object(map("mode","REAL","transactionId","UNIT_TRANSACTION","kind","SHARE","allowed",true,"originalProfitSharing",true,"requestHash",hash(r),"validUntil",Instant.now().plusSeconds(60)));org.mockito.Mockito.when(authority.capability(r,"SHARE")).thenReturn(p);org.mockito.Mockito.when(authority.trusted(p)).thenReturn(true);
  var credentials=object(map("merchantId","12345678","merchantSerialNumber","UNIT_SERIAL","publicKeyId","UNIT_PUBLIC","privateKeyPkcs8",Base64.getEncoder().encodeToString(keys.getPrivate().getEncoded()),"publicKeyX509",Base64.getEncoder().encodeToString(keys.getPublic().getEncoded())));var secured=new Stage45WechatFunds(credentials,authority,()->false);
  assertThrows(Stage1Exception.class,()->org.springframework.test.util.ReflectionTestUtils.invokeMethod(secured,"capability",r));p.addProperty("alreadyUnfrozen",true);assertThrows(Stage1Exception.class,()->org.springframework.test.util.ReflectionTestUtils.invokeMethod(secured,"capability",r));p.addProperty("alreadyUnfrozen",false);assertDoesNotThrow(()->org.springframework.test.util.ReflectionTestUtils.invokeMethod(secured,"capability",r));
 }

 @Test void offByDefaultRejectsBeforeCredentialParsingOrAnyOutbound(){var settings=new Stage1Settings();assertThrows(Stage1Exception.class,()->Stage45WechatFunds.real(settings,new JsonObject(),null));assertThrows(Stage1Exception.class,()->adapter.send(request("REFUND")));assertThrows(Stage1Exception.class,()->adapter.query(request("REFUND")));}
 @Test void onlyEcommercePathsAndFrozenOriginalIdentifiersAreMapped(){for(String kind:List.of("SHARE","RETURN","REFUND","FINISH")){var r=request(kind);r.addProperty("kind",kind);var call=Stage45WechatFunds.call(r,false);assertTrue(call.uri().startsWith("/v3/ecommerce/"));assertEquals("POST",call.method());assertTrue(Stage45WechatFunds.call(r,true).uri().contains("S45_UNIT_REQUEST"));if(kind.equals("SHARE"))assertFalse(call.body().get("finish").getAsBoolean());if(kind.equals("REFUND")){assertEquals("REFUND_SOURCE_SUB_MERCHANT",call.body().get("refund_account").getAsString());assertFalse(call.body().has("funds_account"));assertFalse(call.body().has("from"));}r.addProperty("mode","MOCK");assertThrows(Stage1Exception.class,()->Stage45WechatFunds.call(r,false));}}
 @Test void nativeFinishedWithClosedReceiverCountsOnly300()throws Exception{var r=request("SHARE");r.addProperty("kind","SHARE");var result=adapter.normalize(r,proof(r,sharing("CLOSED"),true));assertEquals("FAILED",result.get("state").getAsString());assertEquals("PARTIAL_FINAL",result.get("detailState").getAsString());assertEquals(300,result.get("succeededCent").getAsLong());assertTrue(adapter.trusted(result));}
 @Test void nativeFinishedWithPendingReceiverRemainsProcessing()throws Exception{var r=request("SHARE");r.addProperty("kind","SHARE");var result=adapter.normalize(r,proof(r,sharing("PENDING"),true));assertEquals("PROCESSING",result.get("state").getAsString());assertEquals(300,result.get("succeededCent").getAsLong());}
 @Test void refundPostIsAcceptanceAndQueryRequiresActualFinalEvidence()throws Exception{var r=request("REFUND");r.addProperty("kind","REFUND");var accepted=adapter.normalize(r,proof(r,object(map("out_refund_no","S45_UNIT_REQUEST","refund_id","UNIT_REFUND")),false));assertEquals("PROCESSING",accepted.get("state").getAsString());assertEquals(0,accepted.get("succeededCent").getAsLong());var body=object(map("out_refund_no","S45_UNIT_REQUEST","transaction_id","UNIT_TRANSACTION","status","SUCCESS","success_time",AT,"amount",map("refund",500,"payer_refund",500,"currency","CNY")));var result=adapter.normalize(r,proof(r,body,true));assertEquals("SUCCEEDED",result.get("state").getAsString());assertEquals(500,result.get("succeededCent").getAsLong());body.remove("success_time");var invalid=proof(r,body,true);assertThrows(Stage1Exception.class,()->adapter.normalize(r,invalid));}
}
